      // unlike ContinuousRectangleBorder which needs 2× the visual radius.
      cardTheme: CardThemeData(
        color: isDark ? AppColors.surface0D : AppColors.surface0,
        surfaceTintColor: Colors.transparent,
        elevation: 0,
        margin: EdgeInsets.zero,
