128	
129	class _DiscoveryView extends ConsumerStatefulWidget {
130	  const _DiscoveryView({required this.petId});
131	  final String petId;
132	
133	  @override
134	  ConsumerState<_DiscoveryView> createState() => _DiscoveryViewState();
135	}
136	
137	class _DiscoveryViewState extends ConsumerState<_DiscoveryView>
138	    with WidgetsBindingObserver {
139	  final Set<String> _shownMatchIds = {};
140	  PetMutualMatch? _celebrationMatch;
141	  Timer? _refreshDebounce;
142	
143	  // Track the last known access state so we only reload candidates when it
144	  // transitions from blocked → granted (H-4 fix).
145	  LocationAccessState? _lastKnownAccess;
146	
147	  String get petId => widget.petId;
148	
149	  @override
150	  void initState() {
151	    super.initState();
152	    WidgetsBinding.instance.addObserver(this);
153	    WidgetsBinding.instance.addPostFrameCallback((_) => _refreshLocationState());
154	  }
155	
156	  @override
157	  void dispose() {
158	    _refreshDebounce?.cancel();
159	    WidgetsBinding.instance.removeObserver(this);
160	    super.dispose();
161	  }
162	
163	  @override
164	  void didChangeAppLifecycleState(AppLifecycleState state) {
165	    if (state != AppLifecycleState.resumed) return;
166	    ref.invalidate(locationAccessProvider);
167	    ref.invalidate(deviceLatLngProvider);
168	    final current = ref.read(locationAccessProvider).asData?.value;
169	    // Full candidate reload only when access changes from blocked → granted.
170	    final wasBlocked = _isLocationBlocked(_lastKnownAccess);
171	    final nowGranted = current == LocationAccessState.granted;
172	    if (wasBlocked && nowGranted) {
173	      ref.invalidate(discoveryCandidatesControllerProvider);
174	    }
175	    _lastKnownAccess = current;
176	  }
177	
178	  // Debounced so rapid lifecycle transitions (e.g. debug-VM attach, permission
179	  // dialogs) collapse into a single invalidation instead of a request storm.
180	  void _refreshLocationState() {
181	    _refreshDebounce?.cancel();
182	    _refreshDebounce = Timer(const Duration(milliseconds: 600), () {
183	      if (!mounted) return;
184	      ref.invalidate(locationAccessProvider);
185	      ref.invalidate(deviceLatLngProvider);
186	      ref.invalidate(discoveryCandidatesControllerProvider);
187	      _lastKnownAccess = ref.read(locationAccessProvider).asData?.value;
188	    });
189	  }
190	
191	  @override
192	  Widget build(BuildContext context) {
193	    ref.listen<AsyncValue<PetMutualMatch>>(
194	      mutualMatchInsertStreamProvider(petId),
195	      (previous, next) {
196	        next.whenData((match) {
197	          if (_shownMatchIds.contains(match.id)) return;
198	          if (_celebrationMatch != null) return;
199	          _shownMatchIds.add(match.id);
200	          setState(() => _celebrationMatch = match);
201	        });
202	      },
203	    );
204	
205	    ref.listen(
206	      locationSyncErrorProvider,
207	      (_, error) {
208	        if (error != null) AppSnackBar.showError(error);
209	      },
210	    );
211	
212	    ref.listen<String?>(
213	      swipeErrorProvider,
214	      (_, message) {
215	        if (message != null) {
216	          ScaffoldMessenger.of(context).showSnackBar(
217	            SnackBar(
