2	import 'package:petfolio/core/theme/theme.dart';
3	
4	
5	class BoneSliderWidget extends StatelessWidget {
6	  const BoneSliderWidget({
7	    super.key,
8	    required this.value,
9	    required this.onChanged,
10	    this.min = 0.0,
11	    this.max = 100.0,
12	    this.color = AppColors.tangerine,
13	  });
14	
15	  final double value;
16	  final ValueChanged<double> onChanged;
17	  final double min;
18	  final double max;
19	  final Color color;
20	
21	  static const double _thumbW = 44.0;
22	  static const double _totalH = 64.0;
23	
24	  double get _pct => ((value - min) / (max - min)).clamp(0.0, 1.0);
25	
26	  @override
27	  Widget build(BuildContext context) {
28	    return LayoutBuilder(
29	      builder: (context, constraints) {
30	        final w = constraints.maxWidth;
31	        final trackW = w - _thumbW;
32	
33	        return GestureDetector(
34	          behavior: HitTestBehavior.opaque,
35	          onHorizontalDragUpdate: (d) {
36	            final box = context.findRenderObject() as RenderBox;
37	            final lx = box.globalToLocal(d.globalPosition).dx;
38	            final raw = ((lx - _thumbW / 2) / trackW).clamp(0.0, 1.0);
39	            onChanged(min + raw * (max - min));
40	          },
41	          onTapDown: (d) {
42	            final box = context.findRenderObject() as RenderBox;
43	            final lx = box.globalToLocal(d.globalPosition).dx;
44	            final raw = ((lx - _thumbW / 2) / trackW).clamp(0.0, 1.0);
45	            onChanged(min + raw * (max - min));
46	          },
47	          child: SizedBox(
48	            height: _totalH,
49	            width: w,
50	            child: CustomPaint(
51	              painter: _BoneSliderPainter(
52	                pct: _pct, 
53	                color: color,
54	                pt: Theme.of(context).extension<PetfolioThemeExtension>()!,
55	              ),
56	            ),
57	          ),
58	        );
59	      },
60	    );
61	  }
62	}
63	
64	class _BoneSliderPainter extends CustomPainter {
65	  const _BoneSliderPainter({required this.pct, required this.color, required this.pt});
66	
67	  final double pct;
68	  final Color color;
69	  final PetfolioThemeExtension pt;
70	
71	  static const _thumbW = 44.0;
72	  static const _trackH = 8.0;
73	
74	  @override
75	  void paint(Canvas canvas, Size size) {
76	    final w = size.width;
77	    final cy = size.height / 2;
78	    final tl = _thumbW / 2;
79	    final tr = w - _thumbW / 2;
80	    final tw = tr - tl;
81	    final thumbX = tl + tw * pct;
82	
83	    // Inactive track
84	    canvas.drawRRect(
85	      RRect.fromRectAndRadius(
86	        Rect.fromLTWH(tl, cy - _trackH / 2, tw, _trackH),
87	        const Radius.circular(PetfolioThemeExtension.radiusPill),
88	      ),
89	      Paint()..color = color.withAlpha(35),
90	    );
91	
92	    // Active track with gradient
93	    if (pct > 0.002) {
94	      canvas.drawRRect(
95	        RRect.fromRectAndRadius(
96	          Rect.fromLTWH(tl, cy - _trackH / 2, tw * pct, _trackH),
97	          const Radius.circular(PetfolioThemeExtension.radiusPill),
98	        ),
99	        Paint()
100	          ..shader = LinearGradient(
101	            colors: [color, AppColors.poppy],
102	          ).createShader(Rect.fromLTWH(tl, cy - _trackH / 2, tw, _trackH)),
103	      );
104	    }
105	
106	    // Thumb shadow
107	    if (pt.shadowE2.isNotEmpty) {
108	      final shadow = pt.shadowE2.first;
109	      canvas.drawCircle(
110	        Offset(thumbX + shadow.offset.dx, cy + shadow.offset.dy),
111	        _thumbW / 2,
112	        Paint()
113	          ..color = shadow.color
114	          ..maskFilter = MaskFilter.blur(BlurStyle.normal, shadow.blurRadius),
115	      );
116	    }
117	
118	    // Bone thumb
119	    final bw = _thumbW;
120	    final bh = 28.0;
121	    final r = bh / 2;
122	    final knobR = r * 0.7;
123	    final hw = bw / 2 - knobR * 0.5;
124	    final hh = r * 0.4;
125	
126	    final bonePath = Path()
127	      ..addRRect(RRect.fromRectAndRadius(
128	        Rect.fromCenter(center: Offset(thumbX, cy), width: hw * 2, height: hh * 2),
129	        Radius.circular(hh),
130	      ));
131	    for (final o in [
132	      Offset(thumbX - hw, cy - hh),
133	      Offset(thumbX - hw, cy + hh),
134	      Offset(thumbX + hw, cy - hh),
135	      Offset(thumbX + hw, cy + hh),
136	    ]) {
137	      bonePath.addOval(Rect.fromCircle(center: o, radius: knobR));
138	    }
139	
140	    canvas.drawPath(bonePath, Paint()..color = Colors.white);
141	    canvas.drawPath(
142	      bonePath,
143	      Paint()
144	        ..color = color
145	        ..style = PaintingStyle.stroke
146	        ..strokeWidth = 2.5,
147	    );
148	  }
149	
150	  @override
151	  bool shouldRepaint(_BoneSliderPainter old) => old.pct != pct || old.color != color;
152	}
