16	class HealthVaultController extends StreamNotifier<List<MedicalRecord>> {
17	  @override
18	  Stream<List<MedicalRecord>> build() {
19	    final petId = ref.watch(activePetIdProvider);
20	    if (petId == null) {
21	      return Stream.value(<MedicalRecord>[]);
22	    }
23	    return Supabase.instance.client
24	        .from('medical_vault')
25	        .stream(primaryKey: ['id'])
26	        .eq('pet_id', petId)
27	        .limit(100)
28	        .map((rows) {
29	          final records = rows
30	              .where((r) => r['is_active'] == true)
31	              .map(MedicalRecord.fromJson)
32	              .toList()
33	            ..sort((a, b) {
34	              final DateTime? keyA = a.nextDueAt ?? a.expiresAt ?? a.administeredAt;
